#!/usr/bin/env bash
# Generated by coding-tooling (environment-v1). Do not edit this copy: change the canonical
# templates/codex-environment.sh in moritzbrantner/coding-tooling, then run
# `coding-tooling environment generate`. Repository-specific setup belongs in
# .repository-environment.toml.
set -euo pipefail

mode="${1:-setup}"
if [[ "$mode" != "setup" && "$mode" != "maintenance" ]]; then
  printf 'usage: %s [setup|maintenance]\n' "$0" >&2
  exit 2
fi

root="$(git rev-parse --show-toplevel)"
config="$root/.repository-environment.toml"

if [[ ! -f "$config" ]]; then
  printf 'missing environment-v1 config: %s\n' "$config" >&2
  exit 2
fi

run_privileged() {
  if command -v sudo >/dev/null 2>&1; then
    sudo "$@"
  else
    "$@"
  fi
}

publish_path() {
  if [[ -n "${GITHUB_PATH:-}" ]]; then
    printf '%s\n' "$1" >> "$GITHUB_PATH"
  fi
}

# Print a TOML value from a file, one line per array item; nothing when the file or key is
# absent. Python's tomllib is used when present (3.11+); Bun's parser covers images whose Python
# is older, such as Ubuntu 22.04's 3.10.
toml_values() {
  if command -v python3 >/dev/null 2>&1 && python3 -c 'import tomllib' >/dev/null 2>&1; then
    python3 - "$1" "$2" <<'PY'
import pathlib, sys, tomllib
path = pathlib.Path(sys.argv[1])
value = tomllib.loads(path.read_text()) if path.is_file() else {}
for part in sys.argv[2].split('.'):
    value = value.get(part) if isinstance(value, dict) else None
for item in value if isinstance(value, list) else [] if value is None else [value]:
    print(item)
PY
  elif command -v bun >/dev/null 2>&1; then
    bun -e '
const [file, key] = process.argv.slice(1);
const fs = require("node:fs");
let value = fs.existsSync(file) ? Bun.TOML.parse(fs.readFileSync(file, "utf8")) : {};
for (const part of key.split(".")) value = value?.[part];
for (const item of Array.isArray(value) ? value : value == null ? [] : [value]) console.log(String(item));
' "$1" "$2"
  else
    printf 'environment-v1 needs Python 3.11+ (tomllib) or Bun to read %s\n' "$1" >&2
    return 2
  fi
}

# Read TOML values into an array. Capturing first makes a parser failure abort under `set -e`
# instead of silently yielding an empty list.
read_lines() {
  local -n target="$1"
  local output
  output="$(toml_values "$2" "$3")"
  target=()
  if [[ -n "$output" ]]; then
    mapfile -t target <<<"$output"
  fi
}

if [[ "$mode" == "setup" ]] && command -v apt-get >/dev/null 2>&1; then
  read_lines apt_packages "$config" system.apt
  # Skip packages that are already dpkg-installed so apt, and its mirror, is only contacted for
  # real gaps. Environment verification checks dpkg state, so a same-named binary outside dpkg
  # (such as a runner's /usr/local/bin/cmake) does not count.
  missing_apt_packages=()
  for package in "${apt_packages[@]}"; do
    if [[ "$(dpkg-query -W -f='${db:Status-Abbrev}' "$package" 2>/dev/null || true)" != ii* ]]; then
      missing_apt_packages+=("$package")
    fi
  done
  if (( ${#missing_apt_packages[@]} )); then
    apt_options=(-o Acquire::Retries=3 -o Acquire::http::Timeout=30 -o Acquire::https::Timeout=30)
    # Declared packages come from Ubuntu itself, so a runner's third-party feeds (which can be
    # slow or broken) are left out of the index update when the distribution source is known.
    if [[ -f /etc/apt/sources.list.d/ubuntu.sources ]]; then
      apt_options+=(-o Dir::Etc::sourcelist=/etc/apt/sources.list.d/ubuntu.sources -o Dir::Etc::sourceparts=-)
    fi
    run_privileged apt-get "${apt_options[@]}" update
    run_privileged apt-get "${apt_options[@]}" install -y --no-install-recommends "${missing_apt_packages[@]}"
  fi
fi

# Toolchains track the latest stable release (owner decision 2026-10-23): declarations are
# minimums, so any installed Bun, Node or Rust release satisfies them.
desired_bun=""
if [[ -f "$root/package.json" ]]; then
  desired_bun="$(sed -n 's/.*"packageManager"[[:space:]]*:[[:space:]]*"bun@\([^"]*\)".*/\1/p' "$root/package.json" | head -n 1)"
fi
if [[ -z "$desired_bun" && -f "$root/.bun-version" ]]; then
  desired_bun="$(tr -d '[:space:]' < "$root/.bun-version")"
fi
if [[ -n "$desired_bun" ]]; then
  if [[ -d "$HOME/.bun/bin" ]]; then
    export PATH="$HOME/.bun/bin:$PATH"
    publish_path "$HOME/.bun/bin"
  fi
  if ! command -v bun >/dev/null 2>&1; then
    printf 'Bun is required (declared %s) but is not installed; install the latest stable Bun before running this script\n' "$desired_bun" >&2
    exit 2
  fi
fi

if [[ -f "$root/.node-version" ]] && ! command -v node >/dev/null 2>&1; then
  printf 'Node is required (.node-version %s) but is not installed; install the latest stable Node before running this script\n' "$(tr -d '[:space:]' < "$root/.node-version")" >&2
  exit 2
fi

rust_toolchain="$(toml_values "$root/rust-toolchain.toml" toolchain.channel)"
if [[ -n "$rust_toolchain" ]]; then
  if [[ -d "$HOME/.cargo/bin" ]]; then
    export PATH="$HOME/.cargo/bin:$PATH"
    publish_path "$HOME/.cargo/bin"
  fi
  if ! command -v rustup >/dev/null 2>&1; then
    printf 'rustup is required to provision Rust %s; install rustup before running this script\n' "$rust_toolchain" >&2
    exit 2
  fi
  rustup toolchain install "$rust_toolchain" --profile minimal
  read_lines rust_components "$root/rust-toolchain.toml" toolchain.components
  for component in "${rust_components[@]}"; do
    rustup component add --toolchain "$rust_toolchain" "$component"
  done
fi

read_lines environment_commands "$config" "$mode.commands"
for command in "${environment_commands[@]}"; do
  (cd "$root" && bash -lc "$command")
done
